{
  "summary": "Start by constructing a table to calculate the accepted and attempted outputs per lane, ensuring only the latest revision is used and retired lanes are ignored.",
  "actions": [
    {
      "tool": "construct_table",
      "name": "table.json",
      "schema": {
        "events": {
          "lane": "TEXT",
          "revision": "INTEGER",
          "state": "TEXT",
          "accepted": "INTEGER",
          "attempts": "INTEGER"
        }
      },
      "sql": "SELECT ledger.lane, ledger.revision, ledger.state, ledger.accepted, ledger.attempts FROM ledger WHERE ledger.state = 'active' AND ledger.revision = (SELECT MAX(revision) FROM ledger WHERE ledger.lane = ledger.lane AND ledger.state = 'active')"
    }
  ],
  "done": false
}
